1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  createProjectSchema,
5	  createProjectWorkspaceSchema,
6	  findWorkspaceCommandDefinition,
7	  isUuidLike,
8	  matchWorkspaceRuntimeServiceToCommand,
9	  updateProjectSchema,
10	  updateProjectWorkspaceSchema,
11	  workspaceRuntimeControlTargetSchema,
12	} from "@paperclipai/shared";
13	import type { WorkspaceRuntimeDesiredState, WorkspaceRuntimeServiceStateMap } from "@paperclipai/shared";
14	import { trackProjectCreated } from "@paperclipai/shared/telemetry";
15	import { validate } from "../middleware/validate.js";
16	import { projectService, logActivity, workspaceOperationService } from "../services/index.js";
17	import { conflict, forbidden } from "../errors.js";
18	import { assertCompanyAccess, getActorInfo } from "./authz.js";
19	import {
20	  buildWorkspaceRuntimeDesiredStatePatch,
21	  listConfiguredRuntimeServiceEntries,
22	  runWorkspaceJobForControl,
23	  startRuntimeServicesForWorkspaceControl,
24	  stopRuntimeServicesForProjectWorkspace,
25	} from "../services/workspace-runtime.js";
26	import {
27	  assertNoAgentHostWorkspaceCommandMutation,
28	  collectProjectExecutionWorkspaceCommandPaths,
29	  collectProjectWorkspaceCommandPaths,
30	} from "./workspace-command-authz.js";
31	import { assertCanManageProjectWorkspaceRuntimeServices } from "./workspace-runtime-service-authz.js";
32	import { getTelemetryClient } from "../telemetry.js";
33	import { appendWithCap } from "../adapters/utils.js";
34	import { assertEnvironmentSelectionForCompany } from "./environment-selection.js";
35	import { environmentService } from "../services/environments.js";
36	import { secretService } from "../services/secrets.js";
37	import type { Handler } from "../http/types.js";
38	import { expressHandler } from "../http/express-adapter.js";
39	
40	const WORKSPACE_CONTROL_OUTPUT_MAX_CHARS = 256 * 1024;
41	const SHARED_WORKSPACE_STOP_AND_RESTART_ACTIONS = new Set(["stop", "restart"]);
42	
43	export function projectRoutes(db: Db) {
44	  const router = Router();
45	  const svc = projectService(db);
46	  const secretsSvc = secretService(db);
47	  const workspaceOperations = workspaceOperationService(db);
48	  const strictSecretsMode = process.env.PAPERCLIP_SECRETS_STRICT_MODE === "true";
49	  const environmentsSvc = environmentService(db);
50	
51	  async function assertProjectEnvironmentSelection(companyId: string, environmentId: string | null | undefined) {
52	    if (environmentId === undefined || environmentId === null) return;
53	    await assertEnvironmentSelectionForCompany(environmentsSvc, companyId, environmentId, {
54	      allowedDrivers: ["local", "ssh", "sandbox"],
55	    });
56	  }
57	
58	  function readProjectPolicyEnvironmentId(policy: unknown): string | null | undefined {
59	    if (!policy || typeof policy !== "object" || !("environmentId" in policy)) {
60	      return undefined;
61	    }
62	    const environmentId = (policy as { environmentId?: unknown }).environmentId;
63	    return typeof environmentId === "string" || environmentId === null ? environmentId : undefined;
64	  }
65	
66	  async function resolveCompanyIdForProjectReference(req: Request) {
67	    const companyIdQuery = req.query.companyId;
68	    const requestedCompanyId =
69	      typeof companyIdQuery === "string" && companyIdQuery.trim().length > 0
70	        ? companyIdQuery.trim()
71	        : null;
72	    if (requestedCompanyId) {
73	      assertCompanyAccess(req, requestedCompanyId);
74	      return requestedCompanyId;
75	    }
76	    if (req.actor.type === "agent" && req.actor.companyId) {
77	      return req.actor.companyId;
78	    }
79	    return null;
80	  }
81	
82	  async function normalizeProjectReference(req: Request, rawId: string) {
83	    if (isUuidLike(rawId)) return rawId;
84	    const companyId = await resolveCompanyIdForProjectReference(req);
85	    if (!companyId) return rawId;
86	    const resolved = await svc.resolveByReference(companyId, rawId);
87	    if (resolved.ambiguous) {
88	      throw conflict("Project shortname is ambiguous in this company. Use the project ID.");
89	    }
90	    return resolved.project?.id ?? rawId;
91	  }
92	
93	  router.param("id", async (req, _res, next, rawId) => {
94	    try {
95	      req.params.id = await normalizeProjectReference(req, rawId);
96	      next();
97	    } catch (err) {
98	      next(err);
99	    }
100	  });
101	
102	  // Storage is not used by project handlers; supply a sentinel to satisfy AdapterDeps.
103	  const storageSentinel = new Proxy({} as import("../storage/types.js").StorageService, {
104	    get(_target, prop) {
105	      throw new Error(`project handler unexpectedly accessed storage.${String(prop)}`);
106	    },
107	  });
108	
109	  const listProjects: Handler = async (ctx) => {
110	    const req = ctx as unknown as Request;
111	    const companyId = ctx.param("companyId")!;
112	    assertCompanyAccess(req, companyId);
113	    const result = await svc.list(companyId);
114	    return Response.json(result);
115	  };
116	
117	  const getProject: Handler = async (ctx) => {
118	    const req = ctx as unknown as Request;
119	    const id = ctx.param("id")!;
120	    const project = await svc.getById(id);
121	    if (!project) {
122	      return Response.json({ error: "Project not found" }, { status: 404 });
123	    }
124	    assertCompanyAccess(req, project.companyId);
125	    return Response.json(project);
126	  };
127	
128	  const createProject: Handler = async (ctx) => {
129	    const req = ctx as unknown as Request;
130	    const companyId = ctx.param("companyId")!;
131	    assertCompanyAccess(req, companyId);
132	    type CreateProjectPayload = Parameters<typeof svc.create>[1] & {
133	      workspace?: Parameters<typeof svc.createWorkspace>[1];
134	    };
135	
136	    const { workspace, ...projectData } = (await ctx.json()) as CreateProjectPayload;
137	    await assertProjectEnvironmentSelection(
138	      companyId,
139	      readProjectPolicyEnvironmentId(projectData.executionWorkspacePolicy),
140	    );
141	    assertNoAgentHostWorkspaceCommandMutation(
142	      req,
143	      [
144	        ...collectProjectExecutionWorkspaceCommandPaths(projectData.executionWorkspacePolicy),
145	        ...collectProjectWorkspaceCommandPaths(workspace, "workspace"),
146	      ],
147	    );
148	    if (projectData.env !== undefined) {
149	      projectData.env = await secretsSvc.normalizeEnvBindingsForPersistence(
150	        companyId,
151	        projectData.env,
152	        { strictMode: strictSecretsMode, fieldPath: "env" },
153	      );
154	    }
155	    const project = await svc.create(companyId, projectData);
156	    let createdWorkspaceId: string | null = null;
157	    if (workspace) {
158	      const createdWorkspace = await svc.createWorkspace(project.id, workspace);
159	      if (!createdWorkspace) {
160	        await svc.remove(project.id);
161	        return Response.json({ error: "Invalid project workspace payload" }, { status: 422 });
162	      }
163	      createdWorkspaceId = createdWorkspace.id;
164	    }
165	    const hydratedProject = workspace ? await svc.getById(project.id) : project;
166	
167	    const actor = getActorInfo(req);
168	    await logActivity(db, {
169	      companyId,
170	      actorType: actor.actorType,
171	      actorId: actor.actorId,
172	      agentId: actor.agentId,
173	      action: "project.created",
174	      entityType: "project",
175	      entityId: project.id,
176	      details: {
177	        name: project.name,
178	        workspaceId: createdWorkspaceId,
179	        envKeys: project.env ? Object.keys(project.env).sort() : [],
180	      },
181	    });
182	    const telemetryClient = getTelemetryClient();
183	    if (telemetryClient) {
184	      trackProjectCreated(telemetryClient);
185	    }
186	    return Response.json(hydratedProject ?? project, { status: 201 });
187	  };
188	
189	  const updateProject: Handler = async (ctx) => {
190	    const req = ctx as unknown as Request;
191	    const id = ctx.param("id")!;
192	    const existing = await svc.getById(id);
193	    if (!existing) {
194	      return Response.json({ error: "Project not found" }, { status: 404 });
195	    }
196	    assertCompanyAccess(req, existing.companyId);
197	    const body = { ...(await ctx.json<Record<string, unknown>>()) };
198	    assertNoAgentHostWorkspaceCommandMutation(
199	      req,
200	      collectProjectExecutionWorkspaceCommandPaths(body.executionWorkspacePolicy),
201	    );
202	    await assertProjectEnvironmentSelection(
203	      existing.companyId,
204	      readProjectPolicyEnvironmentId(body.executionWorkspacePolicy),
205	    );
206	    if (typeof body.archivedAt === "string") {
207	      body.archivedAt = new Date(body.archivedAt);
208	    }
209	    if (body.env !== undefined) {
210	      body.env = await secretsSvc.normalizeEnvBindingsForPersistence(existing.companyId, body.env, {
211	        strictMode: strictSecretsMode,
212	        fieldPath: "env",
213	      });
214	    }
215	    const project = await svc.update(id, body);
216	    if (!project) {
217	      return Response.json({ error: "Project not found" }, { status: 404 });
218	    }
219	
220	    const actor = getActorInfo(req);
221	    await logActivity(db, {
222	      companyId: project.companyId,
223	      actorType: actor.actorType,
224	      actorId: actor.actorId,
225	      agentId: actor.agentId,
226	      action: "project.updated",
227	      entityType: "project",
228	      entityId: project.id,
229	      details: {
230	        changedKeys: Object.keys(body).sort(),
231	        envKeys:
232	          body.env && typeof body.env === "object" && !Array.isArray(body.env)
233	            ? Object.keys(body.env as Record<string, unknown>).sort()
234	            : undefined,
235	      },
236	    });
237	
238	    return Response.json(project);
239	  };
240	
241	  const listProjectWorkspaces: Handler = async (ctx) => {
242	    const req = ctx as unknown as Request;
243	    const id = ctx.param("id")!;
244	    const existing = await svc.getById(id);
245	    if (!existing) {
246	      return Response.json({ error: "Project not found" }, { status: 404 });
247	    }
248	    assertCompanyAccess(req, existing.companyId);
249	    const workspaces = await svc.listWorkspaces(id);
250	    return Response.json(workspaces);
251	  };
252	
253	  const createProjectWorkspace: Handler = async (ctx) => {
254	    const req = ctx as unknown as Request;
255	    const id = ctx.param("id")!;
256	    const existing = await svc.getById(id);
257	    if (!existing) {
258	      return Response.json({ error: "Project not found" }, { status: 404 });
259	    }
260	    assertCompanyAccess(req, existing.companyId);
261	    const body = await ctx.json();
262	    assertNoAgentHostWorkspaceCommandMutation(
263	      req,
264	      collectProjectWorkspaceCommandPaths(body),
265	    );
266	    const workspace = await svc.createWorkspace(id, body);
267	    if (!workspace) {
268	      return Response.json({ error: "Invalid project workspace payload" }, { status: 422 });
269	    }
270	
271	    const actor = getActorInfo(req);
272	    await logActivity(db, {
273	      companyId: existing.companyId,
274	      actorType: actor.actorType,
275	      actorId: actor.actorId,
276	      agentId: actor.agentId,
277	      action: "project.workspace_created",
278	      entityType: "project",
279	      entityId: id,
280	      details: {
281	        workspaceId: workspace.id,
282	        name: workspace.name,
283	        cwd: workspace.cwd,
284	        isPrimary: workspace.isPrimary,
285	      },
286	    });
287	
288	    return Response.json(workspace, { status: 201 });
289	  };
290	
291	  const updateProjectWorkspace: Handler = async (ctx) => {
292	    const req = ctx as unknown as Request;
293	    const id = ctx.param("id")!;
294	    const workspaceId = ctx.param("workspaceId")!;
295	    const existing = await svc.getById(id);
296	    if (!existing) {
297	      return Response.json({ error: "Project not found" }, { status: 404 });
298	    }
299	    assertCompanyAccess(req, existing.companyId);
300	    const body = await ctx.json();
301	    assertNoAgentHostWorkspaceCommandMutation(
302	      req,
303	      collectProjectWorkspaceCommandPaths(body),
304	    );
305	    const workspaceExists = (await svc.listWorkspaces(id)).some((workspace) => workspace.id === workspaceId);
306	    if (!workspaceExists) {
307	      return Response.json({ error: "Project workspace not found" }, { status: 404 });
308	    }
309	    const workspace = await svc.updateWorkspace(id, workspaceId, body);
310	    if (!workspace) {
311	      return Response.json({ error: "Invalid project workspace payload" }, { status: 422 });
312	    }
313	
314	    const actor = getActorInfo(req);
315	    await logActivity(db, {
316	      companyId: existing.companyId,
317	      actorType: actor.actorType,
318	      actorId: actor.actorId,
319	      agentId: actor.agentId,
320	      action: "project.workspace_updated",
321	      entityType: "project",
322	      entityId: id,
323	      details: {
324	        workspaceId: workspace.id,
325	        changedKeys: Object.keys(body as Record<string, unknown>).sort(),
326	      },
327	    });
328	
329	    return Response.json(workspace);
330	  };
331	
332	  const handleProjectWorkspaceRuntimeCommand: Handler = async (ctx) => {
333	    const req = ctx as unknown as Request;
334	    const id = ctx.param("id")!;
335	    const workspaceId = ctx.param("workspaceId")!;
336	    const action = String(ctx.param("action") ?? "").trim().toLowerCase();
337	    if (action !== "start" && action !== "stop" && action !== "restart" && action !== "run") {
338	      return Response.json({ error: "Workspace command action not found" }, { status: 404 });
339	    }
340	
341	    const project = await svc.getById(id);
342	    if (!project) {
343	      return Response.json({ error: "Project not found" }, { status: 404 });
344	    }
345	    assertCompanyAccess(req, project.companyId);
346	
347	    const workspace = project.workspaces.find((entry) => entry.id === workspaceId) ?? null;
348	    if (!workspace) {
349	      return Response.json({ error: "Project workspace not found" }, { status: 404 });
350	    }
351	
352	    const isSharedWorkspace = Boolean(workspace.sharedWorkspaceKey);
353	    if (
354	      req.actor.type === "agent"
355	      && isSharedWorkspace
356	      && SHARED_WORKSPACE_STOP_AND_RESTART_ACTIONS.has(action)
357	    ) {
358	      throw forbidden("Missing permission to manage workspace runtime services");
359	    }
360	
361	    await assertCanManageProjectWorkspaceRuntimeServices(db, req, {
362	      companyId: project.companyId,
363	      projectWorkspaceId: workspace.id,
364	    });
365	
366	    const workspaceCwd = workspace.cwd;
367	    if (!workspaceCwd) {
368	      return Response.json({ error: "Project workspace needs a local path before Paperclip can run workspace commands" }, { status: 422 });
369	    }
370	
371	    const runtimeConfig = workspace.runtimeConfig?.workspaceRuntime ?? null;
372	    const target = (await ctx.json()) as { workspaceCommandId?: string | null; runtimeServiceId?: string | null; serviceIndex?: number | null };
373	    const configuredServices = runtimeConfig ? listConfiguredRuntimeServiceEntries({ workspaceRuntime: runtimeConfig }) : [];
374	    const workspaceCommand = runtimeConfig
375	      ? findWorkspaceCommandDefinition(runtimeConfig, target.workspaceCommandId ?? null)
376	      : null;
377	    if (target.workspaceCommandId && !workspaceCommand) {
378	      return Response.json({ error: "Workspace command not found for this project workspace" }, { status: 404 });
379	    }
380	    if (target.runtimeServiceId && !(workspace.runtimeServices ?? []).some((service) => service.id === target.runtimeServiceId)) {
381	      return Response.json({ error: "Runtime service not found for this project workspace" }, { status: 404 });
382	    }
383	    const matchedRuntimeService =
384	      workspaceCommand?.kind === "service" && !target.runtimeServiceId
385	        ? matchWorkspaceRuntimeServiceToCommand(workspaceCommand, workspace.runtimeServices ?? [])
386	        : null;
387	    const selectedRuntimeServiceId = target.runtimeServiceId ?? matchedRuntimeService?.id ?? null;
388	    const selectedServiceIndex =
389	      workspaceCommand?.kind === "service"
390	        ? workspaceCommand.serviceIndex
391	        : target.serviceIndex ?? null;
392	    if (
393	      selectedServiceIndex !== undefined
394	      && selectedServiceIndex !== null
395	      && (selectedServiceIndex < 0 || selectedServiceIndex >= configuredServices.length)
396	    ) {
397	      return Response.json({ error: "Selected runtime service is not defined in this project workspace runtime config" }, { status: 422 });
398	    }
399	    if (workspaceCommand?.kind === "job" && action !== "run") {
400	      return Response.json({ error: `Workspace job "${workspaceCommand.name}" can only be run` }, { status: 422 });
401	    }
402	    if (workspaceCommand?.kind === "service" && action === "run") {
403	      return Response.json({ error: `Workspace service "${workspaceCommand.name}" should be started or restarted, not run` }, { status: 422 });
404	    }
405	    if (action === "run" && !workspaceCommand) {
406	      return Response.json({ error: "Select a workspace job to run" }, { status: 422 });
407	    }
408	    if ((action === "start" || action === "restart") && !runtimeConfig) {
409	      return Response.json({ error: "Project workspace has no workspace command configuration" }, { status: 422 });
410	    }
411	
412	    const actor = getActorInfo(req);
413	    const recorder = workspaceOperations.createRecorder({ companyId: project.companyId });
414	    let runtimeServiceCount = workspace.runtimeServices?.length ?? 0;
415	    let stdout = "";
416	    let stderr = "";
417	
418	    const operation = await recorder.recordOperation({
419	      phase: action === "stop" ? "workspace_teardown" : "workspace_provision",
420	      command: workspaceCommand?.command ?? `workspace command ${action}`,
421	      cwd: workspace.cwd,
422	      metadata: {
423	        action,
424	        projectId: project.id,
425	        projectWorkspaceId: workspace.id,
426	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
427	        workspaceCommandKind: workspaceCommand?.kind ?? null,
428	        workspaceCommandName: workspaceCommand?.name ?? null,
429	        runtimeServiceId: selectedRuntimeServiceId,
430	        serviceIndex: selectedServiceIndex,
431	      },
432	      run: async () => {
433	        if (action === "run") {
434	          if (!workspaceCommand || workspaceCommand.kind !== "job") {
435	            throw new Error("Workspace job selection is required");
436	          }
437	          return await runWorkspaceJobForControl({
438	            actor: {
439	              id: actor.agentId ?? null,
440	              name: actor.actorType === "user" ? "Board" : "Agent",
441	              companyId: project.companyId,
442	            },
443	            issue: null,
444	            workspace: {
445	              baseCwd: workspaceCwd,
446	              source: "project_primary",
447	              projectId: project.id,
448	              workspaceId: workspace.id,
449	              repoUrl: workspace.repoUrl,
450	              repoRef: workspace.repoRef,
451	              strategy: "project_primary",
452	              cwd: workspaceCwd,
453	              branchName: workspace.defaultRef ?? workspace.repoRef ?? null,
454	              worktreePath: null,
455	              warnings: [],
456	              created: false,
457	            },
458	            command: workspaceCommand.rawConfig,
459	            adapterEnv: {},
460	            recorder,
461	            metadata: {
462	              action,
463	              projectId: project.id,
464	              projectWorkspaceId: workspace.id,
465	              workspaceCommandId: workspaceCommand.id,
466	            },
467	          }).then((nestedOperation) => ({
468	            status: "succeeded" as const,
469	            exitCode: 0,
470	            metadata: {
471	              nestedOperationId: nestedOperation?.id ?? null,
472	              runtimeServiceCount,
473	            },
474	          }));
475	        }
476	
477	        const onLog = async (stream: "stdout" | "stderr", chunk: string) => {
478	          if (stream === "stdout") stdout = appendWithCap(stdout, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
479	          else stderr = appendWithCap(stderr, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
480	        };
481	
482	        if (action === "stop" || action === "restart") {
483	          await stopRuntimeServicesForProjectWorkspace({
484	            db,
485	            projectWorkspaceId: workspace.id,
486	            runtimeServiceId: selectedRuntimeServiceId,
487	          });
488	        }
489	
490	        if (action === "start" || action === "restart") {
491	          const startedServices = await startRuntimeServicesForWorkspaceControl({
492	            db,
493	            actor: {
494	              id: actor.agentId ?? null,
495	              name: actor.actorType === "user" ? "Board" : "Agent",
496	              companyId: project.companyId,
497	            },
498	            issue: null,
499	            workspace: {
500	              baseCwd: workspaceCwd,
501	              source: "project_primary",
502	              projectId: project.id,
503	              workspaceId: workspace.id,
504	              repoUrl: workspace.repoUrl,
505	              repoRef: workspace.repoRef,
506	              strategy: "project_primary",
507	              cwd: workspaceCwd,
508	              branchName: workspace.defaultRef ?? workspace.repoRef ?? null,
509	              worktreePath: null,
510	              warnings: [],
511	              created: false,
512	            },
513	            config: { workspaceRuntime: runtimeConfig },
514	            adapterEnv: {},
515	            onLog,
516	            serviceIndex: selectedServiceIndex,
517	          });
518	          runtimeServiceCount = startedServices.length;
519	        } else {
520	          runtimeServiceCount = selectedRuntimeServiceId ? Math.max(0, (workspace.runtimeServices?.length ?? 1) - 1) : 0;
521	        }
522	
523	        const currentDesiredState: WorkspaceRuntimeDesiredState =
524	          workspace.runtimeConfig?.desiredState
525	          ?? ((workspace.runtimeServices ?? []).some((service) => service.status === "starting" || service.status === "running")
526	            ? "running"
527	            : "stopped");
528	        const nextRuntimeState: {
529	          desiredState: WorkspaceRuntimeDesiredState;
530	          serviceStates: WorkspaceRuntimeServiceStateMap | null | undefined;
531	        } = selectedRuntimeServiceId && (selectedServiceIndex === undefined || selectedServiceIndex === null)
532	          ? {
533	              desiredState: currentDesiredState,
534	              serviceStates: workspace.runtimeConfig?.serviceStates ?? null,
535	            }
536	          : buildWorkspaceRuntimeDesiredStatePatch({
537	              config: { workspaceRuntime: runtimeConfig },
538	              currentDesiredState,
539	              currentServiceStates: workspace.runtimeConfig?.serviceStates ?? null,
540	              action,
541	              serviceIndex: selectedServiceIndex,
542	            });
543	        await svc.updateWorkspace(project.id, workspace.id, {
544	          runtimeConfig: {
545	            desiredState: nextRuntimeState.desiredState,
546	            serviceStates: nextRuntimeState.serviceStates,
547	          },
548	        });
549	
550	        return {
551	          status: "succeeded",
552	          stdout,
553	          stderr,
554	          system:
555	            action === "stop"
556	              ? "Stopped project workspace runtime services.\nThis does not pause issue work or held wake scheduling."
557	              : action === "restart"
558	                ? "Restarted project workspace runtime services.\nThis does not pause issue work or held wake scheduling."
559	                : "Started project workspace runtime services.\n",
560	          metadata: {
561	            runtimeServiceCount,
562	            workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
563	            runtimeServiceId: selectedRuntimeServiceId,
564	            serviceIndex: selectedServiceIndex,
565	          },
566	        };
567	      },
568	    });
569	
570	    const updatedWorkspace = (await svc.listWorkspaces(project.id)).find((entry) => entry.id === workspace.id) ?? workspace;
571	
572	    await logActivity(db, {
573	      companyId: project.companyId,
574	      actorType: actor.actorType,
575	      actorId: actor.actorId,
576	      agentId: actor.agentId,
577	      action: `project.workspace_runtime_${action}`,
578	      entityType: "project",
579	      entityId: project.id,
580	      details: {
581	        projectWorkspaceId: workspace.id,
582	        runtimeServiceCount,
583	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
584	        workspaceCommandKind: workspaceCommand?.kind ?? null,
585	        workspaceCommandName: workspaceCommand?.name ?? null,
586	        runtimeServiceId: selectedRuntimeServiceId,
587	        serviceIndex: selectedServiceIndex,
588	      },
589	    });
590	
591	    return Response.json({
592	      workspace: updatedWorkspace,
593	      operation,
594	    });
595	  };
596	
597	  const deleteProjectWorkspace: Handler = async (ctx) => {
598	    const req = ctx as unknown as Request;
599	    const id = ctx.param("id")!;
600	    const workspaceId = ctx.param("workspaceId")!;
601	    const existing = await svc.getById(id);
602	    if (!existing) {
603	      return Response.json({ error: "Project not found" }, { status: 404 });
604	    }
605	    assertCompanyAccess(req, existing.companyId);
